// Embedded verbatim from scripts/route-monitoring/fetch-prefectures.mjs's prefectures[] array
// (6 department prefecture sites, all confirmed live/HTML/unauthenticated by the 2026-07-21 source-shape probe).
const config = $items('Set Connector Config')[0].json;
const prefectures = [{"department":"33","name":"Préfecture de la Gironde","url":"https://www.gironde.gouv.fr/Actualites"},{"department":"47","name":"Préfecture de Lot-et-Garonne","url":"https://www.lot-et-garonne.gouv.fr/Actualites"},{"department":"82","name":"Préfecture de Tarn-et-Garonne","url":"https://www.tarn-et-garonne.gouv.fr/Actualites"},{"department":"31","name":"Préfecture de la Haute-Garonne","url":"https://www.haute-garonne.gouv.fr/Actualites"},{"department":"11","name":"Préfecture de l'Aude","url":"https://www.aude.gouv.fr/Actualites"},{"department":"34","name":"Préfecture de l'Hérault","url":"https://www.herault.gouv.fr/Actualites"}];
return prefectures.map((p) => ({ json: { ...p, generatedAt: config.generatedAt } }));

// Faithful adaptation of scripts/route-monitoring/fetch-prefectures.mjs's listing/article fetch,
// extractCards(), genericArticlePattern prescreen, and hazardTermPattern/routeTermPattern inclusion gate.
// Runs entirely in one Code node (runOnceForAllItems) using this.helpers.httpRequest because the real
// flow spans 6 department listing pages plus conditional per-article follow-up fetches - a shape n8n's
// single-endpoint HTTP Request node cannot express directly (same reasoning as 06_CANAL_STATUS's VNF
// discovery node).
const prefectureItems = $input.all().map((i) => i.json || {});

function escapeRegExp(value) { return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function normalizeText(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['`]/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
const routeTermPattern = new RegExp(['canal du midi','canal lateral','canal de garonne','canal des deux mers','voie verte','piste cyclable','chemin de halage','velo','cyclable','cycliste'].map(escapeRegExp).join('|'), 'i');
const hazardTermPattern = new RegExp(['fermeture','coupure','travaux','chantier','deviation','inondation','crue','incendie','feu de foret','acces interdit','circulation interdite','restriction de circulation','interdiction de circuler','route barree','effondrement','glissement de terrain'].map(escapeRegExp).join('|'), 'i');
const genericArticlePattern = new RegExp(['fermeture au public','accueil du public',"services de l'etat",'service public',"horaires d'ouverture",'bons reflexes','sensibilisation','campagne de prevention',"campagne d'information",'journee nationale','journee internationale','ceremonie','commemoration','recrutement','appel a projets','appel a candidatures','enquete publique','consultation publique','elections','carte grise','titre de sejour','permis de conduire','demarches administratives','france services'].map(escapeRegExp).join('|'), 'i');

const namedEntities = { amp:'&', apos:"'", gt:'>', lt:'<', nbsp:' ', quot:'"', rsquo:"'", laquo:'«', raquo:'»', eacute:'é', egrave:'è', ecirc:'ê', agrave:'à', ugrave:'ù', ccedil:'ç', ocirc:'ô', icirc:'î' };
function decodeEntities(value) {
  return String(value || '').replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (match, entity) => {
    const lower = entity.toLowerCase();
    if (lower.startsWith('#x')) return String.fromCodePoint(Number.parseInt(lower.slice(2), 16));
    if (lower.startsWith('#')) return String.fromCodePoint(Number.parseInt(lower.slice(1), 10));
    return namedEntities[lower] !== undefined ? namedEntities[lower] : match;
  });
}
function stripHtml(html) {
  return decodeEntities(String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}
function excerpt(text, maxLength) {
  maxLength = maxLength || 900;
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (clean.length <= maxLength) return clean;
  return clean.slice(0, maxLength - 1).trim() + '…';
}
function extractAttr(tag, attrName) {
  const match = String(tag || '').match(new RegExp(attrName + '\\s*=\\s*(["\'])(.*?)\\1', 'i'));
  return match ? decodeEntities(match[2]) : null;
}
function resolveUrl(href, baseUrl) {
  // Manual absolute/relative URL resolver - the global URL constructor is confirmed UNAVAILABLE in
  // this n8n instance's Code-node sandbox (empirically confirmed live during 06_CANAL_STATUS testing).
  const value = String(href || '').trim();
  if (!value) return null;
  if (/^https?:\/\//i.test(value)) return value;
  const originMatch = baseUrl.match(/^(https?:\/\/[^/]+)/i);
  const origin = originMatch ? originMatch[1] : baseUrl;
  if (value.startsWith('/')) return origin + value;
  if (/^(mailto:|tel:|javascript:|data:|#)/i.test(value)) return null;
  return origin + '/' + value;
}
function extractCards(html, baseUrl) {
  const matches = [...html.matchAll(/<h2\b[^>]*class=(["'])[^"']*fr-card__title[^"']*\1[^>]*>[\s\S]*?<a\b([^>]*)>([\s\S]*?)<\/a>[\s\S]*?<\/h2>/gi)];
  return matches.map((match, index) => {
    const href = extractAttr(match[2], 'href');
    const url = href ? resolveUrl(decodeEntities(href), baseUrl) : null;
    const nextIndex = matches[index + 1] ? matches[index + 1].index : Math.min(html.length, match.index + 2500);
    const cardHtml = html.slice(match.index, nextIndex);
    const dateMatch = cardHtml.match(/Publi\u00e9 le\s+(\d{2})\/(\d{2})\/(\d{4})/i);
    const publishedAt = dateMatch ? (dateMatch[3] + '-' + dateMatch[2] + '-' + dateMatch[1] + 'T12:00:00.000Z') : null;
    return { title: stripHtml(match[3]), url, publishedAt, listingText: stripHtml(cardHtml) };
  }).filter((entry) => entry.title && entry.url);
}
function extractMainHtml(html) {
  const article = html.match(/<article\b[\s\S]*?<\/article>/i);
  if (article) return article[0];
  const main = html.match(/<main\b[\s\S]*?<\/main>/i);
  if (main) return main[0];
  return html;
}
function extractArticleBody(html) {
  const main = extractMainHtml(html);
  const h1 = main.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);
  const title = h1 ? stripHtml(h1[1]).replace(/\s+-\s+Les services de l'\u00c9tat.*$/i, '').trim() : null;
  const text = stripHtml(main);
  const body = title && text.startsWith(title) ? text.slice(title.length).trim() : text;
  return { title, bodyText: body };
}
function detectListingStructureWarning(html) {
  const normalized = String(html || '');
  if (normalized.length > 0 && normalized.length < 1500) return 'listing body unexpectedly small (' + normalized.length + ' bytes)';
  if (!/fr-card__title/i.test(normalized)) return 'listing markup missing expected fr-card__title entries';
  return null;
}
function matchesFilter(article) {
  const text = normalizeText((article.title || '') + ' ' + (article.listingText || ''));
  if (genericArticlePattern.test(text)) return false;
  return hazardTermPattern.test(text) || routeTermPattern.test(text);
}

async function fetchText(url) {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url,
        timeout: 25000,
        returnFullResponse: true,
        headers: {
          'User-Agent': 'BikeTourFrance-CDM-RouteMonitor/0.1 (+https://biketourfrance.net; route status research)',
          Accept: 'text/html,application/xhtml+xml,application/xml,text/plain;q=0.9,*/*;q=0.8',
        },
      });
      return typeof response.body === 'string' ? response.body : String(response.body);
    } catch (err) {
      lastError = err;
      const message = String(err && err.message ? err.message : err);
      const retryable = /socket hang up|ECONNRESET|ETIMEDOUT|EAI_AGAIN|503|502|504/i.test(message);
      if (!retryable || attempt === 3) throw err;
      await new Promise((resolve) => setTimeout(resolve, attempt * 1500));
    }
  }
  throw lastError;
}

const checkedAt = new Date().toISOString();
const fetchMetaItems = [];
const rawArticleItems = [];

for (const prefecture of prefectureItems) {
  const sourceId = 'prefecture-' + prefecture.department;
  const meta = {
    recordKind: 'sourceFetchMeta',
    sourceId,
    sourceName: prefecture.name,
    sourceUrl: prefecture.url,
    department: prefecture.department,
    checkedAt,
    ok: true,
    listingArticles: 0,
    matchingArticles: 0,
    articleFetches: 0,
    candidates: 0,
    ignoredArticles: [],
    errors: [],
  };
  try {
    const listingHtml = await fetchText.call(this, prefecture.url);
    meta.listingBytes = listingHtml.length;
    const structureWarning = detectListingStructureWarning(listingHtml);
    if (structureWarning) {
      meta.ok = false;
      meta.structureWarning = structureWarning;
      meta.errors.push({ stage: 'listing', type: 'source_shape_changed', message: 'listing fetch returned unexpected content: ' + structureWarning });
      fetchMetaItems.push(meta);
      continue;
    }
    const cards = extractCards(listingHtml, prefecture.url);
    meta.listingArticles = cards.length;
    const matching = [];
    for (const card of cards) {
      if (matchesFilter(card)) {
        matching.push(card);
      } else {
        const text = normalizeText((card.title || '') + ' ' + (card.listingText || ''));
        if (hazardTermPattern.test(text) || genericArticlePattern.test(text)) {
          meta.ignoredArticles.push({
            title: card.title,
            url: card.url,
            reason: genericArticlePattern.test(text)
              ? 'generic administrative or public-information article (listing prescreen)'
              : 'no route term or route-relevant framing (listing prescreen)',
          });
        }
      }
    }
    meta.matchingArticles = matching.length;
    for (const card of matching) {
      let bodyText = '';
      let articleTitle = card.title;
      try {
        const articleHtml = await fetchText.call(this, card.url);
        meta.articleFetches += 1;
        const article = extractArticleBody(articleHtml);
        bodyText = article.bodyText || card.listingText || '';
        articleTitle = article.title || card.title;
      } catch (err) {
        meta.errors.push({ stage: 'article', type: 'fetch_error', articleUrl: card.url, message: err.message });
        bodyText = card.listingText || '';
      }
      meta.candidates += 1;
      rawArticleItems.push({
        recordKind: 'rawArticle',
        sourceId,
        sourceName: prefecture.name,
        sourceUrl: prefecture.url,
        department: prefecture.department,
        title: articleTitle,
        articleUrl: card.url,
        publishedAt: card.publishedAt,
        bodyText,
        checkedAt,
      });
    }
  } catch (err) {
    meta.ok = false;
    meta.errors.push({ stage: 'listing', type: 'fetch_error', message: err.message, status: err.httpCode || null });
  }
  fetchMetaItems.push(meta);
}

return [...fetchMetaItems.map((m) => ({ json: m })), ...rawArticleItems.map((a) => ({ json: a }))];

// Source-shape probe (2026-07-21) confirmed ZERO PDF hrefs on any of the six prefecture listing
// pages for this connector (unlike 06_CANAL_STATUS's VNF source, which does require PDF handling).
// This node is a documented, evidence-based no-op passthrough - kept in the workflow to preserve
// the standard 21-node connector shape and to make future PDF-document handling a trivial addition
// if a prefecture ever links a PDF, without inventing document fetching that has no current basis.
return $input.all();

// Passes sourceFetchMeta records through unchanged; converts rawArticle records into parsed candidate
// records with a cleaned evidence excerpt, mirroring fetch-prefectures.mjs's excerpt()/normalizeText().
const items = $input.all().map((i) => i.json || {});
function excerpt(text, maxLength) {
  maxLength = maxLength || 1200;
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (clean.length <= maxLength) return clean;
  return clean.slice(0, maxLength - 1).trim() + '\u2026';
}
return items.map((item) => {
  if (item.recordKind !== 'rawArticle') return { json: item };
  const bodyExcerpt = excerpt(item.bodyText, 1000);
  const evidenceText = excerpt((item.title || '') + '. ' + bodyExcerpt, 1400);
  return {
    json: {
      recordKind: 'parsedGovernmentItem',
      sourceId: item.sourceId,
      sourceName: item.sourceName,
      sourceUrl: item.sourceUrl,
      department: item.department,
      title: item.title,
      summary: excerpt(bodyExcerpt, 280),
      evidenceText,
      articleUrl: item.articleUrl,
      publishedAt: item.publishedAt,
      checkedAt: item.checkedAt,
    },
  };
});

// Classifies each parsedGovernmentItem into an official-notice-type / alert-category taxonomy derived
// from fetch-prefectures.mjs's eventTypeFor() hazard-term buckets. Never classifies any category as a
// route closure by default - official government alert type/status stays official.
const items = $input.all().map((i) => i.json || {});
function normalize(value) {
  return String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function classify(text) {
  const n = normalize(text);
  if (/(inondation|crue)/.test(n)) return { officialAlertCategory: 'flood_safety_notice', officialGovernmentStatus: 'flood_hazard_notice' };
  if (/(incendie|feu de foret)/.test(n)) return { officialAlertCategory: 'fire_safety_notice', officialGovernmentStatus: 'fire_hazard_notice' };
  if (/(vigilance|canicule|meteo|baine|orage)/.test(n)) return { officialAlertCategory: 'weather_safety_notice', officialGovernmentStatus: 'weather_alert_notice' };
  if (/(deviation)/.test(n)) return { officialAlertCategory: 'road_access_notice', officialGovernmentStatus: 'detour_notice' };
  if (/(travaux|chantier)/.test(n)) return { officialAlertCategory: 'road_access_notice', officialGovernmentStatus: 'works_notice' };
  if (/(fermeture|coupure)/.test(n)) return { officialAlertCategory: 'road_access_notice', officialGovernmentStatus: 'closure_notice' };
  if (/(acces interdit|interdit|restriction|circulation)/.test(n)) return { officialAlertCategory: 'public_access_notice', officialGovernmentStatus: 'access_restriction_notice' };
  if (/(effondrement|glissement de terrain)/.test(n)) return { officialAlertCategory: 'civil_security_notice', officialGovernmentStatus: 'civil_security_notice' };
  return { officialAlertCategory: 'informational_notice', officialGovernmentStatus: 'notice_published' };
}
function noticeType(category) {
  if (category === 'road_access_notice') return 'public_access_notice';
  if (category === 'public_access_notice') return 'public_access_notice';
  if (category === 'fire_safety_notice' || category === 'flood_safety_notice' || category === 'weather_safety_notice') return 'public_safety_notice';
  if (category === 'civil_security_notice') return 'emergency_notice';
  return 'prefecture_notice';
}
return items.map((item) => {
  if (item.recordKind !== 'parsedGovernmentItem') return { json: item };
  const c = classify(item.evidenceText);
  const officialNoticeType = noticeType(c.officialAlertCategory);
  return { json: { ...item, ...c, officialNoticeType } };
});

// Detects EXPLICIT official route/towpath/public-access impact per the strict CDM domain-boundary rule:
// a general government safety alert alone is never route status. routeImpactStatus only becomes
// "reported" when the evidence text contains an explicit combined phrase from the task's own French
// term list, OR a cycling-infrastructure term combined with a closure verb - never from keyword presence
// alone (e.g. "velo"/"cyclable" mentioned in an unrelated context does not set routeImpactStatus=reported).
const items = $input.all().map((i) => i.json || {});
const towpathTerm = /(chemin de halage|voie verte|piste cyclable|itin[ée]raire v[ée]lo|route cyclable|acc[èe]s public)/i;
const closureVerb = /(ferm[ée]e?s?|interdit|interrompu|coup[ée]e?s?|barr[ée]e?s?|impact[ée]e?s?)/i;
const explicitPhrases = [
  /chemin de halage ferm/i,
  /voie verte ferm/i,
  /piste cyclable ferm/i,
  /itin[ée]raire v[ée]lo ferm/i,
  /acc[èe]s public interdit/i,
  /d[ée]viation cyclable/i,
  /fermeture du chemin/i,
  /interruption de l.?itin[ée]raire/i,
  /route cyclable impact[ée]e/i,
  /restriction d.?acc[èe]s public/i,
  /interdiction d.?acc[èe]s/i,
  /fermeture au public/i,
