      if (!['ROUTE_RELEVANT_PUBLISHED', 'OFFICIAL_NOT_ROUTE_RELEVANT', 'REQUIRES_HUMAN_REVIEW', 'SOURCE_UNAVAILABLE'].includes(alert.classificationLabel)) {
        shapeError = 'Invalid alert classificationLabel for ' + (alert.externalId || 'unknown');
        break;
      }
    }
  }
  results.push({ json: { stagingPath, finalPath, validJson: !shapeError, bytes: Buffer.byteLength(text, 'utf8'), error: shapeError } });
}
const failures = results.filter((r) => r.json.validJson !== true || r.json.error);
if (failures.length > 0) {
  throw new Error('Staging output validation failed: ' + failures.map((f) => f.json.error || 'unknown error').join(' | '));
}
return results;

const config = $items('Set Connector Config')[0].json;
const validationResults = $items('Validate Written Government Safety Alert Files').map((i) => i.json || {});
const generatedAt = config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const failures = validationResults.filter((r) => r.validJson !== true || r.error);
const errors = failures.map((f) => ({ targetPath: f.stagingPath, message: f.error || 'Output file did not pass validation' }));

const normalizeItemsRaw = $items('Normalize Government Safety Alert Records').map((i) => i.json);
const normalizeItems = normalizeItemsRaw.filter((n) => n.recordKind === 'officialGovernmentAlert');
const officialGovernmentAlertCount = normalizeItems.length;
const routeRelevantPublishedCount = normalizeItems.filter((n) => n.classificationLabel === 'ROUTE_RELEVANT_PUBLISHED').length;
const officialNotRouteRelevantCount = normalizeItems.filter((n) => n.classificationLabel === 'OFFICIAL_NOT_ROUTE_RELEVANT').length;
const manualReviewCount = normalizeItems.filter((n) => n.classificationLabel === 'REQUIRES_HUMAN_REVIEW').length;

const healthItems = $items('Build Source Health').map((i) => i.json);
const sourceApiBlocked = healthItems.some((h) => h.status === 'source_api_blocked');
const sourceShapeChanged = healthItems.some((h) => h.status === 'source_shape_changed');

return [{
  json: {
    recordKind: 'runDiagnostics',
    ok: errors.length === 0,
    connectorId: config.connectorId,
    workflowName: config.workflowName,
    workflowVersion: config.workflowVersion,
    generatedAt,
    completedAt,
    validationStatus: errors.length === 0 ? 'passed' : 'failed',
    sourceStatus: sourceApiBlocked ? 'source_api_blocked' : sourceShapeChanged ? 'source_shape_changed' : 'ok',
    writeStatus: validationResults.length > 0 ? 'attempted' : 'not_attempted',
    infraBlocked: false,
    fileAccessRegression: false,
    sourceApiBlocked,
    sourceShapeChanged,
    outputFilenames: [config.finalOutputPath],
    officialGovernmentAlertCount,
    routeRelevantPublishedCount,
    officialNotRouteRelevantCount,
    manualReviewCount,
    errors,
    warnings: [],
    nextAction: errors.length === 0 ? 'Workflow output promoted to final path after staging validation.' : 'Debug failing node before promotion',
    folderMoveRequired: false,
  },
}];
